CREATE TABLE staff_groups (id BIGSERIAL PRIMARY KEY,hospital_id BIGINT NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT,created_by BIGINT REFERENCES staff_profiles(id) ON DELETE SET NULL,created_at TIMESTAMP NOT NULL DEFAULT now(),UNIQUE(hospital_id,name));
CREATE TABLE staff_group_members (group_id BIGINT NOT NULL REFERENCES staff_groups(id) ON DELETE CASCADE,staff_id BIGINT NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,added_at TIMESTAMP NOT NULL DEFAULT now(),PRIMARY KEY(group_id,staff_id));
CREATE TABLE staff_conversations (id BIGSERIAL PRIMARY KEY,hospital_id BIGINT NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE,conversation_type TEXT NOT NULL DEFAULT 'direct',name TEXT,group_id BIGINT REFERENCES staff_groups(id) ON DELETE SET NULL,created_by BIGINT REFERENCES staff_profiles(id) ON DELETE SET NULL,created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE staff_conversation_members (conversation_id BIGINT NOT NULL REFERENCES staff_conversations(id) ON DELETE CASCADE,staff_id BIGINT NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,joined_at TIMESTAMP NOT NULL DEFAULT now(),last_read_at TIMESTAMP,PRIMARY KEY(conversation_id,staff_id));
CREATE TABLE staff_messages (id BIGSERIAL PRIMARY KEY,conversation_id BIGINT NOT NULL REFERENCES staff_conversations(id) ON DELETE CASCADE,sender_staff_id BIGINT NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,message_type TEXT NOT NULL DEFAULT 'text',body TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE staff_notifications (id BIGSERIAL PRIMARY KEY,hospital_id BIGINT NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE,staff_id BIGINT NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,kind TEXT NOT NULL,title TEXT NOT NULL,body TEXT,entity_type TEXT,entity_id TEXT,read_at TIMESTAMP,created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE staff_calls (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),hospital_id BIGINT NOT NULL REFERENCES hospitals(id) ON DELETE CASCADE,caller_staff_id BIGINT NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,target_staff_id BIGINT REFERENCES staff_profiles(id) ON DELETE CASCADE,group_id BIGINT REFERENCES staff_groups(id) ON DELETE SET NULL,call_type TEXT NOT NULL DEFAULT 'voice',status TEXT NOT NULL DEFAULT 'ringing',offer JSONB,answer JSONB,created_at TIMESTAMP NOT NULL DEFAULT now(),answered_at TIMESTAMP,ended_at TIMESTAMP);
CREATE TABLE staff_call_ice (id BIGSERIAL PRIMARY KEY,call_id UUID NOT NULL REFERENCES staff_calls(id) ON DELETE CASCADE,staff_id BIGINT NOT NULL REFERENCES staff_profiles(id) ON DELETE CASCADE,candidate JSONB NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE INDEX idx_staff_groups_hospital ON staff_groups(hospital_id);CREATE INDEX idx_staff_conv_members_staff ON staff_conversation_members(staff_id,conversation_id);CREATE INDEX idx_staff_messages_conv ON staff_messages(conversation_id,id);CREATE INDEX idx_staff_notifications_staff ON staff_notifications(staff_id,read_at,created_at DESC);CREATE INDEX idx_staff_calls_target ON staff_calls(target_staff_id,status,created_at DESC);CREATE INDEX idx_staff_calls_caller ON staff_calls(caller_staff_id,status,created_at DESC);
INSERT INTO permissions(permission_key,label,category,description) VALUES ('page.communication','Staff communication','Pages','Staff chat, groups, notifications and calls'),('action.communication.use','Use staff communication','Actions','Send staff messages, notifications and calls');
INSERT INTO role_permissions(role,permission_key,allowed) VALUES ('admin','page.communication',true),('admin','action.communication.use',true),('receptionist','page.communication',true),('receptionist','action.communication.use',true),('nurse','page.communication',true),('nurse','action.communication.use',true),('doctor','page.communication',true),('doctor','action.communication.use',true),('lab','page.communication',true),('lab','action.communication.use',true),('pharmacy','page.communication',true),('pharmacy','action.communication.use',true),('pending','page.communication',false),('pending','action.communication.use',false);